import pandas as pd

def total_by_category(frame: pd.DataFrame) -> pd.DataFrame:
    """Return a stable category-level units summary."""
    return frame.groupby("category", as_index=False)["units"].sum()

print(total_by_category(pd.DataFrame({"category": ["A", "A"], "units": [2, 4]})).iloc[0, 1])
